#!/usr/bin/env python3
"""ZOWN: photo and video posts (pick or take photos, upload a video, show them in the Feed and Community).
Run from the expo/ folder:  python3 apply_media_posts.py
All-or-nothing: every change is matched in memory first and nothing is written unless all of it matches."""
import os, sys

NEW_FILES = {
 "__tests__/postMedia.test.js": "import {\n  MAX_PHOTOS, MAX_VIDEO_SECONDS, MAX_PHOTO_BYTES, MAX_VIDEO_BYTES,\n  assetKind, assetToItem, addPicked, removeAt, canPost, remainingPhotos, pickerHint,\n  formatDuration, buildStoragePath, contentTypeFor, extensionFor, toMediaDescriptor,\n  normalizeMedia, clampAspect, gridRows, mediaSummary,\n} from '../lib/postMedia';\n\nconst photo = (n, extra = {}) => ({ uri: `file:///tmp/p${n}.jpg`, type: 'image', width: 1200, height: 900, fileSize: 2_000_000, ...extra });\nconst video = (n, extra = {}) => ({ uri: `file:///tmp/v${n}.mov`, type: 'video', width: 1080, height: 1920, duration: 12_000, fileSize: 20_000_000, ...extra });\n\ndescribe('assetKind / assetToItem', () => {\n  it('reads the picker type first', () => {\n    expect(assetKind({ type: 'image' })).toBe('image');\n    expect(assetKind({ type: 'video' })).toBe('video');\n    expect(assetKind({ type: 'livePhoto' })).toBe('image');\n  });\n  it('falls back to mime type and file extension', () => {\n    expect(assetKind({ mimeType: 'video/mp4' })).toBe('video');\n    expect(assetKind({ uri: 'file:///a/b/clip.MOV' })).toBe('video');\n    expect(assetKind({ uri: 'file:///a/b/pic.heic' })).toBe('image');\n    expect(assetKind({ uri: 'file:///a/b/notes.txt' })).toBe(null);\n    expect(assetKind(null)).toBe(null);\n  });\n  it('maps an asset to our shape and rejects ones without a uri or a known kind', () => {\n    expect(assetToItem(video(1))).toMatchObject({ kind: 'video', durationMs: 12000, width: 1080, height: 1920 });\n    expect(assetToItem(photo(1))).toMatchObject({ kind: 'image', durationMs: null });\n    expect(assetToItem({ type: 'image' })).toBe(null);\n    expect(assetToItem({ uri: 'file:///x.txt' })).toBe(null);\n  });\n});\n\ndescribe('addPicked', () => {\n  it('adds photos up to the limit and explains what it left out', () => {\n    const picked = Array.from({ length: MAX_PHOTOS + 2 }, (_, i) => photo(i));\n    const { items, rejected } = addPicked([], picked);\n    expect(items).toHaveLength(MAX_PHOTOS);\n    expect(rejected).toEqual([`You can add up to ${MAX_PHOTOS} photos per post.`]);\n  });\n\n  it('adds one video', () => {\n    const { items, rejected } = addPicked([], [video(1)]);\n    expect(items).toHaveLength(1);\n    expect(items[0].kind).toBe('video');\n    expect(rejected).toEqual([]);\n  });\n\n  it('does not mix photos and a video, whichever comes first wins', () => {\n    const a = addPicked([], [photo(1), video(1)]);\n    expect(a.items.map((i) => i.kind)).toEqual(['image']);\n    expect(a.rejected[0]).toMatch(/not both/);\n\n    const b = addPicked([], [video(1), photo(1)]);\n    expect(b.items.map((i) => i.kind)).toEqual(['video']);\n    expect(b.rejected[0]).toMatch(/not both/);\n  });\n\n  it('refuses a second video', () => {\n    const first = addPicked([], [video(1)]).items;\n    const { items, rejected } = addPicked(first, [video(2)]);\n    expect(items).toHaveLength(1);\n    expect(rejected).toHaveLength(1);\n  });\n\n  it('refuses videos that are too long or too big', () => {\n    const long = addPicked([], [video(1, { duration: (MAX_VIDEO_SECONDS + 5) * 1000 })]);\n    expect(long.items).toHaveLength(0);\n    expect(long.rejected[0]).toMatch(/60 seconds/);\n\n    const exactlyLimit = addPicked([], [video(2, { duration: MAX_VIDEO_SECONDS * 1000 })]);\n    expect(exactlyLimit.items).toHaveLength(1);\n\n    const big = addPicked([], [video(3, { fileSize: MAX_VIDEO_BYTES + 1 })]);\n    expect(big.items).toHaveLength(0);\n    expect(big.rejected[0]).toMatch(/too large/);\n  });\n\n  it('refuses photos that are too big, and unsupported files', () => {\n    const big = addPicked([], [photo(1, { fileSize: MAX_PHOTO_BYTES + 1 })]);\n    expect(big.items).toHaveLength(0);\n    expect(big.rejected[0]).toMatch(/too large/);\n\n    const bad = addPicked([], [{ uri: 'file:///a.txt' }]);\n    expect(bad.items).toHaveLength(0);\n    expect(bad.rejected[0]).toMatch(/not supported/);\n  });\n\n  it('ignores the same file picked twice and keeps what was already chosen', () => {\n    const first = addPicked([], [photo(1)]).items;\n    const again = addPicked(first, [photo(1), photo(2)]);\n    expect(again.items.map((i) => i.uri)).toEqual(['file:///tmp/p1.jpg', 'file:///tmp/p2.jpg']);\n    expect(again.rejected).toEqual([]);\n  });\n\n  it('accepts items that are already in our shape', () => {\n    const items = addPicked([], [photo(1)]).items;\n    const { items: next } = addPicked(items, items);\n    expect(next).toHaveLength(1);\n  });\n});\n\ndescribe('small helpers', () => {\n  it('removeAt', () => {\n    expect(removeAt([1, 2, 3], 1)).toEqual([1, 3]);\n    expect(removeAt(null, 0)).toEqual([]);\n  });\n\n  it('canPost needs text or media', () => {\n    expect(canPost('', [])).toBe(false);\n    expect(canPost('   ', [])).toBe(false);\n    expect(canPost('hi', [])).toBe(true);\n    expect(canPost('', [{ uri: 'x' }])).toBe(true);\n    expect(canPost(undefined, undefined)).toBe(false);\n  });\n\n  it('remainingPhotos and pickerHint follow what is chosen', () => {\n    expect(remainingPhotos([])).toBe(MAX_PHOTOS);\n    const two = addPicked([], [photo(1), photo(2)]).items;\n    expect(remainingPhotos(two)).toBe(MAX_PHOTOS - 2);\n    expect(pickerHint(two)).toBe(`2/${MAX_PHOTOS} photos`);\n    const vid = addPicked([], [video(1)]).items;\n    expect(remainingPhotos(vid)).toBe(0);\n    expect(pickerHint(vid)).toBe('1 video added');\n    expect(pickerHint([])).toMatch(/Up to 4 photos or 1 video/);\n  });\n\n  it('formatDuration', () => {\n    expect(formatDuration(0)).toBe('0:00');\n    expect(formatDuration(7400)).toBe('0:07');\n    expect(formatDuration(60000)).toBe('1:00');\n    expect(formatDuration(754000)).toBe('12:34');\n    expect(formatDuration(undefined)).toBe('0:00');\n  });\n\n  it('clampAspect keeps media between 4:5 and 1.91:1', () => {\n    expect(clampAspect(1000, 2000)).toBe(0.8);\n    expect(clampAspect(4000, 1000)).toBe(1.91);\n    expect(clampAspect(1200, 900)).toBeCloseTo(4 / 3, 5);\n    expect(clampAspect(null, null)).toBeCloseTo(4 / 3, 5);\n    expect(clampAspect(0, 10, 1)).toBe(1);\n  });\n\n  it('gridRows lays out 1 to 4 photos', () => {\n    expect(gridRows(1)).toEqual([[0]]);\n    expect(gridRows(2)).toEqual([[0, 1]]);\n    expect(gridRows(3)).toEqual([[0], [1, 2]]);\n    expect(gridRows(4)).toEqual([[0, 1], [2, 3]]);\n  });\n\n  it('mediaSummary reads naturally', () => {\n    expect(mediaSummary([])).toBe('');\n    expect(mediaSummary([{ type: 'image' }])).toBe('a photo');\n    expect(mediaSummary([{ type: 'image' }, { type: 'image' }, { type: 'image' }])).toBe('3 photos');\n    expect(mediaSummary([{ type: 'video' }])).toBe('a video');\n  });\n});\n\ndescribe('storage paths and descriptors', () => {\n  it('builds the path the Storage rule allows (posts/{uid}/{postId}/{n}.{ext})', () => {\n    const item = assetToItem(photo(1));\n    expect(buildStoragePath('u1', 'p9', 0, item)).toBe('posts/u1/p9/0.jpg');\n    expect(buildStoragePath('u1', 'p9', 1, assetToItem(video(1)))).toBe('posts/u1/p9/1.mov');\n  });\n\n  it('picks sensible extensions and content types', () => {\n    expect(extensionFor({ kind: 'image', uri: 'file:///a/b' })).toBe('jpg');\n    expect(extensionFor({ kind: 'video', uri: 'file:///a/b' })).toBe('mp4');\n    expect(contentTypeFor({ kind: 'video', uri: 'file:///a/b.mov' })).toBe('video/quicktime');\n    expect(contentTypeFor({ kind: 'image', uri: 'file:///a/b.png' })).toBe('image/png');\n    expect(contentTypeFor({ kind: 'image', uri: 'file:///a/b.jpg', mimeType: 'image/heic' })).toBe('image/heic');\n    expect(contentTypeFor({ kind: 'video', uri: 'file:///a/b.weird' })).toBe('video/mp4');\n  });\n\n  it('descriptors never contain undefined values (Firestore rejects them)', () => {\n    const d = toMediaDescriptor(assetToItem(video(1)), 'https://x/y', 'posts/u/p/0.mov');\n    expect(d).toEqual({ type: 'video', url: 'https://x/y', path: 'posts/u/p/0.mov', width: 1080, height: 1920, durationMs: 12000 });\n    const bare = toMediaDescriptor({ kind: 'image', uri: 'file:///a.jpg' }, 'https://x/z', 'posts/u/p/0.jpg');\n    expect(bare).toEqual({ type: 'image', url: 'https://x/z', path: 'posts/u/p/0.jpg' });\n    Object.values(d).concat(Object.values(bare)).forEach((v) => expect(v).not.toBeUndefined());\n  });\n});\n\ndescribe('normalizeMedia', () => {\n  it('uses the media list when present', () => {\n    const media = [{ type: 'image', url: 'https://a/1.jpg' }, { type: 'image', url: 'https://a/2.jpg' }];\n    expect(normalizeMedia({ media, imageUrl: 'https://old' })).toEqual(media);\n  });\n  it('falls back to the older imageUrl field', () => {\n    expect(normalizeMedia({ imageUrl: 'https://a/1.jpg' })).toEqual([{ type: 'image', url: 'https://a/1.jpg' }]);\n  });\n  it('drops bad entries and non-http urls', () => {\n    expect(normalizeMedia({ media: [{ type: 'gif', url: 'https://a' }, { type: 'image', url: 'file:///x' }, null] })).toEqual([]);\n    expect(normalizeMedia({ imageUrl: 'file:///x.jpg' })).toEqual([]);\n    expect(normalizeMedia(null)).toEqual([]);\n    expect(normalizeMedia({})).toEqual([]);\n  });\n});\n",
 "components/MediaPickerStrip.jsx": "// components/MediaPickerStrip.jsx\n//\n// The \"add photos or video\" row for a post composer: a library button, a\n// camera button, a hint, and previews of what has been chosen (with a remove\n// button on each). The parent owns the list of items and gets every change\n// through onChange.\n\nimport React from 'react';\nimport { View, Text, Image, Pressable, ScrollView, Alert, StyleSheet } from 'react-native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { pickFromLibrary, capturePhoto } from '../services/postMediaService';\nimport {\n  addPicked, removeAt, remainingPhotos, pickerHint, formatDuration,\n} from '../lib/postMedia';\n\nexport default function MediaPickerStrip({ items, onChange, disabled }) {\n  const list = Array.isArray(items) ? items : [];\n  const full = remainingPhotos(list) === 0;\n\n  const apply = (assets) => {\n    if (!assets || assets.length === 0) return;\n    const { items: next, rejected } = addPicked(list, assets);\n    onChange(next);\n    if (rejected.length > 0) Alert.alert(\"Some files weren't added\", rejected.join('\\n'));\n  };\n\n  const onLibrary = async () => {\n    try {\n      const assets = await pickFromLibrary({ selectionLimit: Math.max(1, remainingPhotos(list)) });\n      apply(assets);\n    } catch (e) {\n      console.warn('[MediaPickerStrip] library failed', e?.message);\n      Alert.alert(\"Couldn't open your photos\", 'Check that Zown HQ can access your photos in Settings, then try again.');\n    }\n  };\n\n  const onCamera = async () => {\n    try {\n      const { denied, assets } = await capturePhoto();\n      if (denied) {\n        Alert.alert('Camera access needed', 'Allow camera access for Zown HQ in Settings to take a photo.');\n        return;\n      }\n      apply(assets);\n    } catch (e) {\n      console.warn('[MediaPickerStrip] camera failed', e?.message);\n      Alert.alert(\"Couldn't open the camera\", 'Please try again.');\n    }\n  };\n\n  const blocked = disabled || full;\n\n  return (\n    <View style={styles.wrap}>\n      <View style={styles.row}>\n        <Pressable\n          onPress={onLibrary}\n          disabled={blocked}\n          style={[styles.btn, blocked && styles.btnOff]}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Add photos or video\"\n        >\n          <Ionicons name=\"images-outline\" size={18} color=\"#000\" />\n          <Text style={styles.btnText}>Photo / Video</Text>\n        </Pressable>\n        <Pressable\n          onPress={onCamera}\n          disabled={blocked}\n          style={[styles.btn, blocked && styles.btnOff]}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Take a photo\"\n        >\n          <Ionicons name=\"camera-outline\" size={18} color=\"#000\" />\n          <Text style={styles.btnText}>Camera</Text>\n        </Pressable>\n        <Text style={styles.hint} numberOfLines={2}>{pickerHint(list)}</Text>\n      </View>\n\n      {list.length > 0 && (\n        <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.previews} contentContainerStyle={{ gap: 8 }}>\n          {list.map((item, i) => (\n            <View key={item.uri} style={styles.preview}>\n              {item.kind === 'video' ? (\n                <View style={[styles.previewImg, styles.videoPreview]}>\n                  <Ionicons name=\"play\" size={22} color=\"#FFF\" />\n                  {!!item.durationMs && <Text style={styles.videoLen}>{formatDuration(item.durationMs)}</Text>}\n                </View>\n              ) : (\n                <Image source={{ uri: item.uri }} style={styles.previewImg} />\n              )}\n              {!disabled && (\n                <Pressable\n                  onPress={() => onChange(removeAt(list, i))}\n                  style={styles.remove}\n                  hitSlop={8}\n                  accessibilityRole=\"button\"\n                  accessibilityLabel=\"Remove\"\n                >\n                  <Ionicons name=\"close\" size={14} color=\"#FFF\" />\n                </Pressable>\n              )}\n            </View>\n          ))}\n        </ScrollView>\n      )}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  wrap: { marginTop: 12 },\n  row: { flexDirection: 'row', alignItems: 'center', gap: 8 },\n  btn: {\n    flexDirection: 'row', alignItems: 'center', gap: 6, borderWidth: 1, borderColor: '#E5E5E5',\n    borderRadius: 18, paddingHorizontal: 12, paddingVertical: 8, backgroundColor: '#FFF',\n  },\n  btnOff: { opacity: 0.4 },\n  btnText: { fontSize: 13, fontWeight: '600', color: '#000' },\n  hint: { flex: 1, fontSize: 11, color: '#999', textAlign: 'right' },\n  previews: { marginTop: 12 },\n  preview: { width: 76, height: 76 },\n  previewImg: { width: 76, height: 76, borderRadius: 12, backgroundColor: '#F0F0F0' },\n  videoPreview: { backgroundColor: '#000', alignItems: 'center', justifyContent: 'center' },\n  videoLen: { color: '#FFF', fontSize: 11, fontWeight: '700', marginTop: 2 },\n  remove: {\n    position: 'absolute', top: -6, right: -6, width: 22, height: 22, borderRadius: 11,\n    backgroundColor: '#000', alignItems: 'center', justifyContent: 'center',\n  },\n});\n",
 "components/PostMedia.jsx": "// components/PostMedia.jsx\n//\n// Shows the photos or video on a post. Photos sit in a grid and open a\n// full-screen swipeable viewer when tapped. A video shows a play tile first\n// and only loads the player once tapped, so a long feed does not start\n// downloading every video.\n\nimport React, { useState } from 'react';\nimport {\n  View, Text, Image, Pressable, Modal, FlatList, StyleSheet, useWindowDimensions,\n} from 'react-native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { Video, Audio, ResizeMode } from 'expo-av';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport { clampAspect, gridRows, formatDuration } from '../lib/postMedia';\n\nasync function allowSoundInSilentMode() {\n  try {\n    // Same settings services/audioPlayerService.js uses, so videos are not muted by the ringer switch.\n    await Audio.setAudioModeAsync({ playsInSilentModeIOS: true, staysActiveInBackground: false, shouldDuckAndroid: true });\n  } catch (e) {\n    // Not fatal: the video still plays, it just follows the ringer switch.\n  }\n}\n\nfunction VideoTile({ item }) {\n  const [active, setActive] = useState(false);\n  const aspectRatio = clampAspect(item.width, item.height, 16 / 9);\n\n  if (!active) {\n    return (\n      <Pressable\n        onPress={() => { allowSoundInSilentMode(); setActive(true); }}\n        style={[styles.videoTile, { aspectRatio }]}\n        accessibilityRole=\"button\"\n        accessibilityLabel=\"Play video\"\n      >\n        <View style={styles.playCircle}>\n          <Ionicons name=\"play\" size={28} color=\"#FFFFFF\" style={{ marginLeft: 3 }} />\n        </View>\n        {!!item.durationMs && (\n          <View style={styles.durationChip}>\n            <Text style={styles.durationText}>{formatDuration(item.durationMs)}</Text>\n          </View>\n        )}\n      </Pressable>\n    );\n  }\n\n  return (\n    <View style={[styles.videoTile, { aspectRatio }]}>\n      <Video\n        source={{ uri: item.url }}\n        style={StyleSheet.absoluteFill}\n        useNativeControls\n        resizeMode={ResizeMode.CONTAIN}\n        shouldPlay\n        isLooping={false}\n      />\n    </View>\n  );\n}\n\nfunction ImageGrid({ images, onOpen }) {\n  if (images.length === 1) {\n    const item = images[0];\n    return (\n      <Pressable onPress={() => onOpen(0)} accessibilityRole=\"imagebutton\" accessibilityLabel=\"Open photo\">\n        <Image\n          source={{ uri: item.url }}\n          style={[styles.single, { aspectRatio: clampAspect(item.width, item.height) }]}\n          resizeMode=\"cover\"\n        />\n      </Pressable>\n    );\n  }\n  const rows = gridRows(images.length);\n  return (\n    <View style={styles.grid}>\n      {rows.map((row, r) => (\n        <View key={r} style={styles.gridRow}>\n          {row.map((index) => (\n            <Pressable\n              key={index}\n              style={[styles.cell, { aspectRatio: row.length === 1 ? 16 / 9 : 1 }]}\n              onPress={() => onOpen(index)}\n              accessibilityRole=\"imagebutton\"\n              accessibilityLabel={`Open photo ${index + 1}`}\n            >\n              <Image source={{ uri: images[index].url }} style={styles.cellImage} resizeMode=\"cover\" />\n            </Pressable>\n          ))}\n        </View>\n      ))}\n    </View>\n  );\n}\n\nfunction Viewer({ images, startIndex, onClose }) {\n  const { width, height } = useWindowDimensions();\n  const insets = useSafeAreaInsets();\n  const [index, setIndex] = useState(startIndex || 0);\n\n  return (\n    <Modal visible transparent animationType=\"fade\" onRequestClose={onClose} statusBarTranslucent>\n      <View style={styles.viewerWrap}>\n        <FlatList\n          data={images}\n          horizontal\n          pagingEnabled\n          showsHorizontalScrollIndicator={false}\n          initialScrollIndex={startIndex || 0}\n          getItemLayout={(_, i) => ({ length: width, offset: width * i, index: i })}\n          keyExtractor={(m, i) => `${m.url}-${i}`}\n          onMomentumScrollEnd={(e) => setIndex(Math.round(e.nativeEvent.contentOffset.x / width))}\n          renderItem={({ item }) => (\n            <View style={{ width, height, justifyContent: 'center' }}>\n              <Image source={{ uri: item.url }} style={{ width, height: height * 0.8 }} resizeMode=\"contain\" />\n            </View>\n          )}\n        />\n        <Pressable\n          onPress={onClose}\n          style={[styles.viewerClose, { top: insets.top + 12 }]}\n          accessibilityRole=\"button\"\n          accessibilityLabel=\"Close\"\n          hitSlop={12}\n        >\n          <Ionicons name=\"close\" size={26} color=\"#FFFFFF\" />\n        </Pressable>\n        {images.length > 1 && (\n          <Text style={[styles.viewerCount, { top: insets.top + 18 }]}>{index + 1} / {images.length}</Text>\n        )}\n      </View>\n    </Modal>\n  );\n}\n\nexport default function PostMedia({ media, style }) {\n  const [viewerIndex, setViewerIndex] = useState(null);\n  if (!Array.isArray(media) || media.length === 0) return null;\n\n  if (media[0].type === 'video') {\n    return (\n      <View style={[styles.wrap, style]}>\n        <VideoTile item={media[0]} />\n      </View>\n    );\n  }\n\n  const images = media.filter((m) => m.type === 'image').slice(0, 4);\n  if (images.length === 0) return null;\n  return (\n    <View style={[styles.wrap, style]}>\n      <ImageGrid images={images} onOpen={setViewerIndex} />\n      {viewerIndex !== null && (\n        <Viewer images={images} startIndex={viewerIndex} onClose={() => setViewerIndex(null)} />\n      )}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  wrap: { marginTop: 10, borderRadius: 14, overflow: 'hidden', backgroundColor: '#F5F5F5' },\n  single: { width: '100%' },\n  grid: { gap: 2 },\n  gridRow: { flexDirection: 'row', gap: 2 },\n  cell: { flex: 1 },\n  cellImage: { width: '100%', height: '100%' },\n  videoTile: { width: '100%', backgroundColor: '#000000', alignItems: 'center', justifyContent: 'center' },\n  playCircle: {\n    width: 58, height: 58, borderRadius: 29, backgroundColor: 'rgba(255,255,255,0.22)',\n    alignItems: 'center', justifyContent: 'center',\n  },\n  durationChip: {\n    position: 'absolute', right: 10, bottom: 10, backgroundColor: 'rgba(0,0,0,0.65)',\n    borderRadius: 8, paddingHorizontal: 8, paddingVertical: 3,\n  },\n  durationText: { color: '#FFFFFF', fontSize: 12, fontWeight: '700' },\n  viewerWrap: { flex: 1, backgroundColor: '#000000' },\n  viewerClose: {\n    position: 'absolute', right: 16, width: 40, height: 40, borderRadius: 20,\n    backgroundColor: 'rgba(255,255,255,0.18)', alignItems: 'center', justifyContent: 'center',\n  },\n  viewerCount: { position: 'absolute', left: 20, color: '#FFFFFF', fontSize: 14, fontWeight: '700' },\n});\n",
 "lib/postMedia.js": "// lib/postMedia.js\n//\n// Pure helpers for photo and video posts (no Firebase, no React Native, so\n// they are easy to test). A post carries either up to 4 photos or one video,\n// the same limits X uses. Raise MAX_PHOTOS here if you want more later; the\n// Storage rules only cap file sizes, not counts.\n\nexport const MAX_PHOTOS = 4;\nexport const MAX_VIDEOS = 1;\nexport const MAX_VIDEO_SECONDS = 60;\nexport const MAX_PHOTO_BYTES = 15 * 1024 * 1024; // keep in sync with storage.rules\nexport const MAX_VIDEO_BYTES = 100 * 1024 * 1024; // keep in sync with storage.rules\n\nconst IMAGE_EXTENSIONS = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', heic: 'image/heic', heif: 'image/heif', webp: 'image/webp', gif: 'image/gif' };\nconst VIDEO_EXTENSIONS = { mp4: 'video/mp4', mov: 'video/quicktime', m4v: 'video/x-m4v', '3gp': 'video/3gpp', webm: 'video/webm' };\n\nfunction extensionOf(uriOrName) {\n  const clean = String(uriOrName || '').split('?')[0].split('#')[0];\n  const match = clean.match(/\\.([a-zA-Z0-9]{2,5})$/);\n  return match ? match[1].toLowerCase() : '';\n}\n\n/** 'image' | 'video' | null for a picker asset (or one of our items). */\nexport function assetKind(asset) {\n  if (!asset) return null;\n  if (asset.kind === 'image' || asset.kind === 'video') return asset.kind;\n  if (asset.type === 'video' || asset.type === 'pairedVideo') return 'video';\n  if (asset.type === 'image' || asset.type === 'livePhoto') return 'image';\n  const mime = String(asset.mimeType || '');\n  if (mime.startsWith('video/')) return 'video';\n  if (mime.startsWith('image/')) return 'image';\n  const ext = extensionOf(asset.fileName || asset.uri);\n  if (VIDEO_EXTENSIONS[ext]) return 'video';\n  if (IMAGE_EXTENSIONS[ext]) return 'image';\n  return null;\n}\n\nexport function extensionFor(item) {\n  const kind = assetKind(item);\n  const ext = extensionOf(item?.fileName) || extensionOf(item?.uri);\n  if (kind === 'video') return VIDEO_EXTENSIONS[ext] ? ext : 'mp4';\n  return IMAGE_EXTENSIONS[ext] ? ext : 'jpg';\n}\n\nexport function contentTypeFor(item) {\n  const kind = assetKind(item);\n  const mime = String(item?.mimeType || '');\n  if (kind === 'video') {\n    if (mime.startsWith('video/')) return mime;\n    return VIDEO_EXTENSIONS[extensionFor(item)] || 'video/mp4';\n  }\n  if (mime.startsWith('image/')) return mime;\n  return IMAGE_EXTENSIONS[extensionFor(item)] || 'image/jpeg';\n}\n\n/** Our own small shape for a picked file. Returns null if it is not a photo or video we can post. */\nexport function assetToItem(asset) {\n  const kind = assetKind(asset);\n  if (!asset || !asset.uri || !kind) return null;\n  return {\n    uri: asset.uri,\n    kind,\n    width: Number(asset.width) > 0 ? Number(asset.width) : null,\n    height: Number(asset.height) > 0 ? Number(asset.height) : null,\n    durationMs: kind === 'video' && Number(asset.duration) > 0 ? Math.round(Number(asset.duration)) : null,\n    fileSize: Number(asset.fileSize) > 0 ? Number(asset.fileSize) : null,\n    mimeType: asset.mimeType || null,\n    fileName: asset.fileName || null,\n  };\n}\n\n/**\n * Adds picked files to what is already chosen, one at a time, enforcing the\n * rules. Returns { items, rejected } where rejected is a de-duplicated list of\n * plain-English reasons to show the person.\n */\nexport function addPicked(existing, picked) {\n  const items = Array.isArray(existing) ? [...existing] : [];\n  const rejected = [];\n  const reject = (reason) => { if (!rejected.includes(reason)) rejected.push(reason); };\n\n  (Array.isArray(picked) ? picked : []).forEach((raw) => {\n    const item = raw && raw.kind && raw.uri && !raw.type ? raw : assetToItem(raw);\n    if (!item) { if (raw) reject('That file type is not supported. Choose a photo or a video.'); return; }\n    if (items.some((it) => it.uri === item.uri)) return;\n\n    const hasVideo = items.some((it) => it.kind === 'video');\n    const photoCount = items.filter((it) => it.kind === 'image').length;\n\n    if (item.kind === 'video') {\n      if (hasVideo || photoCount > 0) { reject('A post can have up to 4 photos or 1 video, not both.'); return; }\n      if (item.durationMs && item.durationMs > MAX_VIDEO_SECONDS * 1000 + 500) { reject(`Videos can be up to ${MAX_VIDEO_SECONDS} seconds.`); return; }\n      if (item.fileSize && item.fileSize > MAX_VIDEO_BYTES) { reject('That video is too large (100 MB max). Try a shorter clip.'); return; }\n      items.push(item);\n      return;\n    }\n\n    if (hasVideo) { reject('A post can have up to 4 photos or 1 video, not both.'); return; }\n    if (photoCount >= MAX_PHOTOS) { reject(`You can add up to ${MAX_PHOTOS} photos per post.`); return; }\n    if (item.fileSize && item.fileSize > MAX_PHOTO_BYTES) { reject('That photo is too large (15 MB max).'); return; }\n    items.push(item);\n  });\n\n  return { items, rejected };\n}\n\nexport function removeAt(items, index) {\n  const list = Array.isArray(items) ? items : [];\n  return list.filter((_, i) => i !== index);\n}\n\n/** A post needs some text or at least one photo or video. */\nexport function canPost(text, items) {\n  return String(text || '').trim().length > 0 || (Array.isArray(items) && items.length > 0);\n}\n\n/** How many more photos can be added (0 once a video is chosen). */\nexport function remainingPhotos(items) {\n  const list = Array.isArray(items) ? items : [];\n  if (list.some((it) => it.kind === 'video')) return 0;\n  return Math.max(0, MAX_PHOTOS - list.filter((it) => it.kind === 'image').length);\n}\n\nexport function pickerHint(items) {\n  const list = Array.isArray(items) ? items : [];\n  if (list.some((it) => it.kind === 'video')) return '1 video added';\n  const photos = list.filter((it) => it.kind === 'image').length;\n  if (photos > 0) return `${photos}/${MAX_PHOTOS} photos`;\n  return `Up to ${MAX_PHOTOS} photos or 1 video (${MAX_VIDEO_SECONDS}s)`;\n}\n\n/** 0:07, 1:00, 12:34 */\nexport function formatDuration(ms) {\n  const total = Math.max(0, Math.round((Number(ms) || 0) / 1000));\n  const m = Math.floor(total / 60);\n  const s = total % 60;\n  return `${m}:${String(s).padStart(2, '0')}`;\n}\n\n/** Where a file goes in Firebase Storage. Matches the `posts/{uid}/{postId}/{file}` rule. */\nexport function buildStoragePath(uid, postId, index, item) {\n  return `posts/${uid}/${postId}/${index}.${extensionFor(item)}`;\n}\n\n/** What gets saved on the post document for one uploaded file (never contains undefined). */\nexport function toMediaDescriptor(item, url, path) {\n  const kind = assetKind(item) || 'image';\n  const out = { type: kind, url, path };\n  if (item?.width) out.width = item.width;\n  if (item?.height) out.height = item.height;\n  if (kind === 'video' && item?.durationMs) out.durationMs = item.durationMs;\n  return out;\n}\n\n/** The media list for a post, including older posts that only have `imageUrl`. */\nexport function normalizeMedia(post) {\n  if (!post) return [];\n  const fromList = Array.isArray(post.media)\n    ? post.media.filter((m) => m && (m.type === 'image' || m.type === 'video') && typeof m.url === 'string' && /^https?:\\/\\//.test(m.url))\n    : [];\n  if (fromList.length > 0) return fromList;\n  if (typeof post.imageUrl === 'string' && /^https?:\\/\\//.test(post.imageUrl)) {\n    return [{ type: 'image', url: post.imageUrl }];\n  }\n  return [];\n}\n\n/** Keeps a photo or video from being absurdly tall or wide in the feed (4:5 up to 1.91:1, like Instagram). */\nexport function clampAspect(width, height, fallback = 4 / 3) {\n  const w = Number(width);\n  const h = Number(height);\n  if (!(w > 0) || !(h > 0)) return fallback;\n  return Math.min(1.91, Math.max(0.8, w / h));\n}\n\n/** Which photo indexes go on which row of the grid. */\nexport function gridRows(count) {\n  if (count <= 1) return [[0]];\n  if (count === 2) return [[0, 1]];\n  if (count === 3) return [[0], [1, 2]];\n  return [[0, 1], [2, 3]];\n}\n\n/** Short phrase for share messages, e.g. \"3 photos\" or \"a video\". */\nexport function mediaSummary(media) {\n  const list = Array.isArray(media) ? media : [];\n  if (list.length === 0) return '';\n  if (list[0].type === 'video') return 'a video';\n  return list.length === 1 ? 'a photo' : `${list.length} photos`;\n}\n",
 "services/postMediaService.js": "// services/postMediaService.js\n//\n// Picking photos and videos, and uploading them to Firebase Storage for a\n// post. Only uses packages that are already in the app (expo-image-picker,\n// firebase/storage), so it ships as an over-the-air update.\n//\n// Files go to posts/{uid}/{postId}/{n}.{ext}. storage.rules lets any signed-in\n// user read them (the feed is public) and only the owner create or delete.\n\nimport * as ImagePicker from 'expo-image-picker';\nimport { ref, uploadBytesResumable, getDownloadURL, deleteObject } from 'firebase/storage';\nimport { storage } from '../src/config/firebase';\nimport {\n  MAX_PHOTOS, MAX_VIDEO_SECONDS, buildStoragePath, contentTypeFor, toMediaDescriptor,\n} from '../lib/postMedia';\n\n/** Opens the photo library for photos and videos. Returns the raw picker assets ([] if cancelled). */\nexport async function pickFromLibrary({ selectionLimit = MAX_PHOTOS } = {}) {\n  const options = {\n    mediaTypes: ['images', 'videos'],\n    allowsMultipleSelection: true,\n    selectionLimit: Math.max(1, selectionLimit),\n    orderedSelection: true,\n    quality: 0.8,\n    videoMaxDuration: MAX_VIDEO_SECONDS,\n  };\n  // iOS: re-encode big videos at medium quality so uploads are smaller and faster.\n  const preset = ImagePicker.VideoExportPreset && ImagePicker.VideoExportPreset.MediumQuality;\n  if (preset !== undefined) options.videoExportPreset = preset;\n\n  const result = await ImagePicker.launchImageLibraryAsync(options);\n  if (result.canceled) return [];\n  return result.assets || [];\n}\n\n/**\n * Takes a photo with the camera. Photos only: recording video from the\n * camera needs a microphone permission string that has not been checked in\n * the shipped build, so video comes from the library for now.\n * Returns { denied, assets }.\n */\nexport async function capturePhoto() {\n  const permission = await ImagePicker.requestCameraPermissionsAsync();\n  if (!permission.granted) return { denied: true, assets: [] };\n  const result = await ImagePicker.launchCameraAsync({ mediaTypes: ['images'], quality: 0.8 });\n  if (result.canceled) return { denied: false, assets: [] };\n  return { denied: false, assets: result.assets || [] };\n}\n\n/**\n * Uploads picked items one after another and returns the media descriptors to\n * save on the post. onProgress gets a number from 0 to 1 across all files.\n * If anything fails, files already uploaded for this post are removed.\n */\nexport async function uploadPostMedia({ uid, postId, items, onProgress }) {\n  const uploaded = [];\n  const media = [];\n  try {\n    for (let i = 0; i < items.length; i += 1) {\n      const item = items[i];\n      const path = buildStoragePath(uid, postId, i, item);\n      const fileRef = ref(storage, path);\n      const response = await fetch(item.uri);\n      const blob = await response.blob();\n      const task = uploadBytesResumable(fileRef, blob, {\n        contentType: contentTypeFor(item),\n        cacheControl: 'public,max-age=31536000',\n      });\n      await new Promise((resolve, reject) => {\n        task.on(\n          'state_changed',\n          (snap) => {\n            if (onProgress && snap.totalBytes > 0) onProgress((i + snap.bytesTransferred / snap.totalBytes) / items.length);\n          },\n          reject,\n          resolve\n        );\n      });\n      if (blob && typeof blob.close === 'function') blob.close();\n      uploaded.push(fileRef);\n      const url = await getDownloadURL(fileRef);\n      media.push(toMediaDescriptor(item, url, path));\n    }\n    if (onProgress) onProgress(1);\n    return media;\n  } catch (e) {\n    await Promise.all(uploaded.map((r) => deleteObject(r).catch(() => {})));\n    throw e;\n  }\n}\n\n/** Best-effort removal of a post's files (only the owner is allowed to, so other deletes quietly do nothing). */\nexport async function deletePostMedia(media) {\n  const list = Array.isArray(media) ? media : [];\n  await Promise.all(\n    list\n      .filter((m) => m && typeof m.path === 'string' && m.path.startsWith('posts/'))\n      .map((m) => deleteObject(ref(storage, m.path)).catch(() => {}))\n  );\n}\n"
}

